import{_ as i,o as a,c as e,a2 as h}from"./chunks/framework.BXzK3EA4.js";const s=JSON.parse('{"title":"운영가문","description":"","frontmatter":{},"headers":[],"relativePath":"world/Operating-Houses.md","filePath":"world/Operating-Houses.md"}'),r={name:"world/Operating-Houses.md"};function o(p,l,t,n,u,c){return a(),e("div",null,[...l[0]||(l[0]=[h('<h1 id="운영가문" tabindex="-1">운영가문 <a class="header-anchor" href="#운영가문" aria-label="Permalink to &quot;운영가문&quot;">​</a></h1><p>이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.</p><ul><li>원본 앵커: <code>docs/game-logic/World-Narrative-Atlas.md</code></li><li>원본 해시: <code>61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1</code></li></ul><h2 id="hc01-·-삼성전자" tabindex="-1">HC01 · 삼성전자 <a class="header-anchor" href="#hc01-·-삼성전자" aria-label="Permalink to &quot;HC01 · 삼성전자&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S01 여의신정수문정부, S09 상암송신공사</li><li>전속 국가: 없음</li><li>스튜어드십: 허은찬</li></ul><p>여의도 제2정수 옆 봉인 전산동에서 삼성전자이 야간 냉각 분배를 지킨다.</p><p>허은찬은 냉각탑 시계를 급수 당직과 맞춰 돌린고 상암 송신키 공유 요구 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>화면이 꺼져도 급수 원장은 남긴다.</p><h3 id="_3막" tabindex="-1">3막 <a class="header-anchor" href="#_3막" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 여의도 제2정수 옆 봉인 전산동에서 야간 냉각 분배가 부족해진다</li><li>2막 교섭: 허은찬이 상암 송신키 공유 요구와 공동 점검을 연다</li><li>3막 대가: 화면이 꺼져도 급수 원장은 남긴다</li></ul><h2 id="hc02-·-현대자동차" tabindex="-1">HC02 · 현대자동차 <a class="header-anchor" href="#hc02-·-현대자동차" aria-label="Permalink to &quot;HC02 · 현대자동차&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S01 여의신정수문정부, S16 수서강남협약도시, S07 용산철도후국</li><li>전속 국가: 없음</li><li>스튜어드십: 유세진</li></ul><p>신정기지 유치선과 수서 회차선에서 현대자동차이 배터리 셀 순환을 지킨다.</p><p>유세진은 회차 슬롯을 화물보다 구급차에 먼저 연다.</p><p>용산 환적 창구 독점 시도 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>선로가 잠겨도 사람 호송은 걷게 연다.</p><h3 id="_3막-1" tabindex="-1">3막 <a class="header-anchor" href="#_3막-1" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 신정기지 유치선과 수서 회차선에서 배터리 셀 순환이 부족해진다</li><li>2막 교섭: 유세진이 용산 환적 창구 독점 시도와 공동 점검을 연다</li><li>3막 대가: 선로가 잠겨도 사람 호송은 걷게 연다</li></ul><h2 id="hc03-·-lg생활건강" tabindex="-1">HC03 · LG생활건강 <a class="header-anchor" href="#hc03-·-lg생활건강" aria-label="Permalink to &quot;HC03 · LG생활건강&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S03 마곡연구평의회, S13 약령의정동맹</li><li>전속 국가: 없음</li><li>스튜어드십: 서이안</li></ul><p>마곡 밀폐실험동 방풍실에서 LG생활건강가 생체 데이터셋 격리 키를 지킨다.</p><p>서이안은 실험 일지를 병상 이름과 분리해 보관한다.</p><p>약령의 원료 선점 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>표본이 사라져도 동의 기록은 태우지 않는다.</p><h3 id="_3막-2" tabindex="-1">3막 <a class="header-anchor" href="#_3막-2" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 마곡 밀폐실험동 방풍실에서 생체 데이터셋 격리 키가 부족해진다</li><li>2막 교섭: 서이안이 약령의 원료 선점와 공동 점검을 연다</li><li>3막 대가: 표본이 사라져도 동의 기록은 태우지 않는다</li></ul><h2 id="hc04-·-sk에너지" tabindex="-1">HC04 · SK에너지 <a class="header-anchor" href="#hc04-·-sk에너지" aria-label="Permalink to &quot;HC04 · SK에너지&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S04 뚝도공방연합, S05 암사고덕상수단, S01 여의신정수문정부</li><li>전속 국가: 없음</li><li>스튜어드십: 박누리</li></ul><p>뚝도 펌프와 암사 여열 배관에서 SK에너지이 지하 열원 접속권을 지킨다.</p><p>박누리는 여열을 팔기 전에 펌프 예비 전력을 채운다.</p><p>여의 급수 야간 우선권 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>정전 순서를 숨기지 않고 게시판에 붙인다.</p><h3 id="_3막-3" tabindex="-1">3막 <a class="header-anchor" href="#_3막-3" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 뚝도 펌프와 암사 여열 배관에서 지하 열원 접속권이 부족해진다</li><li>2막 교섭: 박누리가 여의 급수 야간 우선권와 공동 점검을 연다</li><li>3막 대가: 정전 순서를 숨기지 않고 게시판에 붙인다</li></ul><h2 id="hc05-·-북문지식원" tabindex="-1">HC05 · 북문지식원 <a class="header-anchor" href="#hc05-·-북문지식원" aria-label="Permalink to &quot;HC05 · 북문지식원&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S10 북산피난연맹, S06 도성기록청</li><li>전속 국가: 없음</li><li>스튜어드십: 윤서린</li></ul><p>북한산 회랑 창고의 습도 금고에서 북문지식원이 옛 기록 원본 한 상자를 지킨다.</p><p>윤서린은 습도 알람이 울리면 열람을 멈추고 상자만 옮긴다.</p><p>도성 인준 인지 요구 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>공개 범위를 접어도 목록 자체는 남긴다.</p><h3 id="_3막-4" tabindex="-1">3막 <a class="header-anchor" href="#_3막-4" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 북한산 회랑 창고의 습도 금고에서 옛 기록 원본 한 상자가 부족해진다</li><li>2막 교섭: 윤서린이 도성 인준 인지 요구와 공동 점검을 연다</li><li>3막 대가: 공개 범위를 접어도 목록 자체는 남긴다</li></ul><h2 id="hc06-·-쿠팡" tabindex="-1">HC06 · 쿠팡 <a class="header-anchor" href="#hc06-·-쿠팡" aria-label="Permalink to &quot;HC06 · 쿠팡&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S08 노량진남관상회, S15 가락잠실배급국</li><li>전속 국가: 없음</li><li>스튜어드십: 오해린</li></ul><p>노량진 하층 골목과 가락 후문에서 쿠팡이 근거리 수레 배차권을 지킨다.</p><p>오해린은 골목 순번을 경매 호가와 바꿔 쓰지 않는다.</p><p>장거리 배송단의 진입 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>점포가 비어도 주문 장부는 섞지 않는다.</p><h3 id="_3막-5" tabindex="-1">3막 <a class="header-anchor" href="#_3막-5" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 노량진 하층 골목과 가락 후문에서 근거리 수레 배차권이 부족해진다</li><li>2막 교섭: 오해린이 장거리 배송단의 진입와 공동 점검을 연다</li><li>3막 대가: 점포가 비어도 주문 장부는 섞지 않는다</li></ul><h2 id="hc07-·-포스코" tabindex="-1">HC07 · 포스코 <a class="header-anchor" href="#hc07-·-포스코" aria-label="Permalink to &quot;HC07 · 포스코&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S02 서남제작동맹, S04 뚝도공방연합</li><li>전속 국가: 없음</li><li>스튜어드십: 강민서</li></ul><p>구로 고온로와 성수 합금 정에서 포스코이 내열 합금 레시피를 지킨다.</p><p>강민서는 로 온도가 흔들리면 주문을 받아도 불을 끈다.</p><p>궤도 방위문의 군수용 전용 요구 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>불량이 나와도 규격 도장은 위조하지 않는다.</p><h3 id="_3막-6" tabindex="-1">3막 <a class="header-anchor" href="#_3막-6" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 구로 고온로와 성수 합금 정에서 내열 합금 레시피가 부족해진다</li><li>2막 교섭: 강민서가 궤도 방위문의 군수용 전용 요구와 공동 점검을 연다</li><li>3막 대가: 불량이 나와도 규격 도장은 위조하지 않는다</li></ul><h2 id="hc08-·-한화에어로스페이스" tabindex="-1">HC08 · 한화에어로스페이스 <a class="header-anchor" href="#hc08-·-한화에어로스페이스" aria-label="Permalink to &quot;HC08 · 한화에어로스페이스&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S11 창동차륜방, S12 신내망우환승시, S05 암사고덕상수단</li><li>전속 국가: 없음</li><li>스튜어드십: 김도윤</li></ul><p>창동 북문과 신내 환승 차단문에서 한화에어로스페이스이 통합 방호키를 지킨다.</p><p>김도윤은 차단문 원격키를 호위단에 넘기지 않는다.</p><p>암사 호위단의 원격 잠금 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>시민 통행을 닫기 전에 대피 방송을 먼저 연다.</p><h3 id="_3막-7" tabindex="-1">3막 <a class="header-anchor" href="#_3막-7" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 창동 북문과 신내 환승 차단문에서 통합 방호키가 부족해진다</li><li>2막 교섭: 김도윤이 암사 호위단의 원격 잠금와 공동 점검을 연다</li><li>3막 대가: 시민 통행을 닫기 전에 대피 방송을 먼저 연다</li></ul><h2 id="hc09-·-롯데쇼핑" tabindex="-1">HC09 · 롯데쇼핑 <a class="header-anchor" href="#hc09-·-롯데쇼핑" aria-label="Permalink to &quot;HC09 · 롯데쇼핑&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S06 도성기록청, S15 가락잠실배급국, S08 노량진남관상회</li><li>전속 국가: 없음</li><li>스튜어드십: 남윤경</li></ul><p>서울역 서편 창고와 잠실 하층에서 롯데쇼핑가 생활재 재고 원장을 지킨다.</p><p>남윤경은 창고 열쇠와 가격표를 한 사람이 쥐지 않는다.</p><p>가락 경매 우선권 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>재고가 줄어도 배급 순번을 팔지 않는다.</p><h3 id="_3막-8" tabindex="-1">3막 <a class="header-anchor" href="#_3막-8" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 서울역 서편 창고와 잠실 하층에서 생활재 재고 원장이 부족해진다</li><li>2막 교섭: 남윤경이 가락 경매 우선권와 공동 점검을 연다</li><li>3막 대가: 재고가 줄어도 배급 순번을 팔지 않는다</li></ul><h2 id="hc10-·-cj제일제당" tabindex="-1">HC10 · CJ제일제당 <a class="header-anchor" href="#hc10-·-cj제일제당" aria-label="Permalink to &quot;HC10 · CJ제일제당&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S03 마곡연구평의회, S09 상암송신공사, S08 노량진남관상회</li><li>전속 국가: 없음</li><li>스튜어드십: 문가람</li></ul><p>마곡 종자 창고와 상암 부엌 방송에서 CJ제일제당이 발효 종자 금고를 지킨다.</p><p>문가람은 방송 레시피에 재고 위치를 섞어 쓰지 않는다.</p><p>노량진 냉동 임차 인상 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>맛의 표준을 강요하지 않고 위생 수치만 공개한다.</p><h3 id="_3막-9" tabindex="-1">3막 <a class="header-anchor" href="#_3막-9" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 마곡 종자 창고와 상암 부엌 방송에서 발효 종자 금고가 부족해진다</li><li>2막 교섭: 문가람이 노량진 냉동 임차 인상와 공동 점검을 연다</li><li>3막 대가: 맛의 표준을 강요하지 않고 위생 수치만 공개한다</li></ul><h2 id="hc11-·-cj대한통운" tabindex="-1">HC11 · CJ대한통운 <a class="header-anchor" href="#hc11-·-cj대한통운" aria-label="Permalink to &quot;HC11 · CJ대한통운&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S07 용산철도후국, S12 신내망우환승시, S16 수서강남협약도시</li><li>전속 국가: 없음</li><li>스튜어드십: 박태겸</li></ul><p>용산 화물홈과 수서 심야 슬롯에서 CJ대한통운이 야간 호송 허가증을 지킨다.</p><p>박태겸은 심야 슬롯을 의료열차에 양보한 뒤 화물을 민다.</p><p>신내 의료열차와 충돌 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>빈 상자를 채워 무게를 속이지 않는다.</p><h3 id="_3막-10" tabindex="-1">3막 <a class="header-anchor" href="#_3막-10" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 용산 화물홈과 수서 심야 슬롯에서 야간 호송 허가증이 부족해진다</li><li>2막 교섭: 박태겸이 신내 의료열차와 충돌와 공동 점검을 연다</li><li>3막 대가: 빈 상자를 채워 무게를 속이지 않는다</li></ul><h2 id="hc12-·-현대중공업" tabindex="-1">HC12 · 현대중공업 <a class="header-anchor" href="#hc12-·-현대중공업" aria-label="Permalink to &quot;HC12 · 현대중공업&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S02 서남제작동맹, S14 아차구의관문국, S04 뚝도공방연합</li><li>전속 국가: 없음</li><li>스튜어드십: 정시우</li></ul><p>금천 크레인과 아차 교각 하부에서 현대중공업가 대형 리깅 자격을 지킨다.</p><p>정시우는 교각 아래에 크레인을 세우기 전 풍속을 적는다.</p><p>뚝도 펌프 하우징 쟁탈 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>하중 한도를 넘긴 작업은 기록 전에 멈춘다.</p><h3 id="_3막-11" tabindex="-1">3막 <a class="header-anchor" href="#_3막-11" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 금천 크레인과 아차 교각 하부에서 대형 리깅 자격이 부족해진다</li><li>2막 교섭: 정시우가 뚝도 펌프 하우징 쟁탈와 공동 점검을 연다</li><li>3막 대가: 하중 한도를 넘긴 작업은 기록 전에 멈춘다</li></ul><h2 id="hc13-·-hd현대건설" tabindex="-1">HC13 · HD현대건설 <a class="header-anchor" href="#hc13-·-hd현대건설" aria-label="Permalink to &quot;HC13 · HD현대건설&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S06 도성기록청, S16 수서강남협약도시, S14 아차구의관문국</li><li>전속 국가: 없음</li><li>스튜어드십: 정유라</li></ul><p>도성 잔벽과 수서 지하 공동구에서 HD현대건설이 내진 접합 도면을 지킨다.</p><p>정유라는 공동구 도면을 감시탑 증축과 맞바꿔 팔지 않는다.</p><p>아차 고지 감시탑 증축 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>도면이 틀려도 현장을 숫자로 맞춘다.</p><h3 id="_3막-12" tabindex="-1">3막 <a class="header-anchor" href="#_3막-12" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 도성 잔벽과 수서 지하 공동구에서 내진 접합 도면이 부족해진다</li><li>2막 교섭: 정유라가 아차 고지 감시탑 증축와 공동 점검을 연다</li><li>3막 대가: 도면이 틀려도 현장을 숫자로 맞춘다</li></ul><h2 id="hc14-·-신한지주" tabindex="-1">HC14 · 신한지주 <a class="header-anchor" href="#hc14-·-신한지주" aria-label="Permalink to &quot;HC14 · 신한지주&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S01 여의신정수문정부, S16 수서강남협약도시, S06 도성기록청</li><li>전속 국가: 없음</li><li>스튜어드십: 장필규</li></ul><p>여의도 계약고와 수서 중재실에서 신한지주이 이중서명 장부를 지킨다.</p><p>장필규는 한 서명이 비면 급수 계약을 집행하지 않는다.</p><p>기록청의 인준 지연 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>손실을 숨기지 않고 보상 순서를 공개한다.</p><h3 id="_3막-13" tabindex="-1">3막 <a class="header-anchor" href="#_3막-13" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 여의도 계약고와 수서 중재실에서 이중서명 장부가 부족해진다</li><li>2막 교섭: 장필규가 기록청의 인준 지연와 공동 점검을 연다</li><li>3막 대가: 손실을 숨기지 않고 보상 순서를 공개한다</li></ul><h2 id="hp01-·-아리수수문가" tabindex="-1">HP01 · 아리수수문가 <a class="header-anchor" href="#hp01-·-아리수수문가" aria-label="Permalink to &quot;HP01 · 아리수수문가&quot;">​</a></h2><ul><li>분류: INFRA_OPERATOR</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S01 여의신정수문정부, S04 뚝도공방연합, S05 암사고덕상수단, S14 아차구의관문국</li><li>전속 국가: 없음</li><li>스튜어드십: 한재목</li></ul><p>영등포·뚝도·암사·구의 수문 당직함에서 아리수수문가가 수문 키 분할 보관을 지킨다.</p><p>한재목은 네 곳 키를 한 주머니에 모으지 않는다.</p><p>한 권역의 전면 차수 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>물을 무기로 쓰는 명령을 거부한다.</p><h3 id="_3막-14" tabindex="-1">3막 <a class="header-anchor" href="#_3막-14" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 영등포·뚝도·암사·구의 수문 당직함에서 수문 키 분할 보관이 부족해진다</li><li>2막 교섭: 한재목이 한 권역의 전면 차수와 공동 점검을 연다</li><li>3막 대가: 물을 무기로 쓰는 명령을 거부한다</li></ul><h2 id="hp02-·-환승선로문" tabindex="-1">HP02 · 환승선로문 <a class="header-anchor" href="#hp02-·-환승선로문" aria-label="Permalink to &quot;HP02 · 환승선로문&quot;">​</a></h2><ul><li>분류: INFRA_OPERATOR</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S07 용산철도후국, S12 신내망우환승시, S11 창동차륜방</li><li>전속 국가: 없음</li><li>스튜어드십: 장세화</li></ul><p>용산·신내·창동 배차 회의실에서 환승선로문이 중립 배차표를 지킨다.</p><p>장세화는 전세 열차가 와도 응급 칸을 지우지 않는다.</p><p>강국의 전세 열차 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>응급 이송을 화물보다 뒤에 두지 않는다.</p><h3 id="_3막-15" tabindex="-1">3막 <a class="header-anchor" href="#_3막-15" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 용산·신내·창동 배차 회의실에서 중립 배차표가 부족해진다</li><li>2막 교섭: 장세화가 강국의 전세 열차와 공동 점검을 연다</li><li>3막 대가: 응급 이송을 화물보다 뒤에 두지 않는다</li></ul><h2 id="hp03-·-공동의료원가" tabindex="-1">HP03 · 공동의료원가 <a class="header-anchor" href="#hp03-·-공동의료원가" aria-label="Permalink to &quot;HP03 · 공동의료원가&quot;">​</a></h2><ul><li>분류: PROFESSIONAL_GUILD</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S13 약령의정동맹, S06 도성기록청, S03 마곡연구평의회</li><li>전속 국가: 없음</li><li>스튜어드십: 류은비</li></ul><p>청량리 이송로와 도성 재난의료 데스크에서 공동의료원가가 면허 당직표를 지킨다.</p><p>류은비는 실험 병상 요구가 와도 응급 순번을 팔지 않는다.</p><p>마곡의 실험 병상 전용 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>병상을 편으로 가르지 않는다.</p><h3 id="_3막-16" tabindex="-1">3막 <a class="header-anchor" href="#_3막-16" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 청량리 이송로와 도성 재난의료 데스크에서 면허 당직표가 부족해진다</li><li>2막 교섭: 류은비가 마곡의 실험 병상 전용와 공동 점검을 연다</li><li>3막 대가: 병상을 편으로 가르지 않는다</li></ul><h2 id="hp04-·-도성기록법가" tabindex="-1">HP04 · 도성기록법가 <a class="header-anchor" href="#hp04-·-도성기록법가" aria-label="Permalink to &quot;HP04 · 도성기록법가&quot;">​</a></h2><ul><li>분류: PROFESSIONAL_GUILD</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S06 도성기록청, S09 상암송신공사</li><li>전속 국가: 없음</li><li>스튜어드십: 여리안</li></ul><p>기록고 열람실과 송신 교차검증대에서 도성기록법가가 원본 해시 봉인을 지킨다.</p><p>여리안은 해시가 다른 문서를 먼저 방송하지 않는다.</p><p>방송국의 단독 공개 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>유언 사본 세 장을 한 진본으로 합치지 않는다.</p><h3 id="_3막-17" tabindex="-1">3막 <a class="header-anchor" href="#_3막-17" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 기록고 열람실과 송신 교차검증대에서 원본 해시 봉인이 부족해진다</li><li>2막 교섭: 여리안이 방송국의 단독 공개와 공동 점검을 연다</li><li>3막 대가: 유언 사본 세 장을 한 진본으로 합치지 않는다</li></ul><h2 id="hp05-·-북산귀환회" tabindex="-1">HP05 · 북산귀환회 <a class="header-anchor" href="#hp05-·-북산귀환회" aria-label="Permalink to &quot;HP05 · 북산귀환회&quot;">​</a></h2><ul><li>분류: CIVIC_COMPACT</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S10 북산피난연맹, S11 창동차륜방, S12 신내망우환승시</li><li>전속 국가: 없음</li><li>스튜어드십: 백온</li></ul><p>은평 피난로와 창동 주거쉘 대기줄에서 북산귀환회가 가족 재결합 명부를 지킨다.</p><p>백온은 대기줄 이름을 복무 명부와 맞바꾸지 않는다.</p><p>군사호적 재등록 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>명부를 인질로 쓰지 않고 본인 동의로만 연다.</p><h3 id="_3막-18" tabindex="-1">3막 <a class="header-anchor" href="#_3막-18" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 은평 피난로와 창동 주거쉘 대기줄에서 가족 재결합 명부가 부족해진다</li><li>2막 교섭: 백온이 군사호적 재등록와 공동 점검을 연다</li><li>3막 대가: 명부를 인질로 쓰지 않고 본인 동의로만 연다</li></ul><h2 id="hp06-·-약령치유문" tabindex="-1">HP06 · 약령치유문 <a class="header-anchor" href="#hp06-·-약령치유문" aria-label="Permalink to &quot;HP06 · 약령치유문&quot;">​</a></h2><ul><li>분류: PROFESSIONAL_GUILD</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S13 약령의정동맹, S03 마곡연구평의회, S10 북산피난연맹</li><li>전속 국가: 없음</li><li>스튜어드십: 정하린</li></ul><p>약령 조제실과 마곡 방역 시료실에서 약령치유문이 처방 이중확인을 지킨다.</p><p>정하린은 독점 구매서보다 로트 불량을 먼저 붙인다.</p><p>북산 약초 독점 구매 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>가짜 약을 숨기지 않고 로트 번호를 게시한다.</p><h3 id="_3막-19" tabindex="-1">3막 <a class="header-anchor" href="#_3막-19" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 약령 조제실과 마곡 방역 시료실에서 처방 이중확인이 부족해진다</li><li>2막 교섭: 정하린이 북산 약초 독점 구매와 공동 점검을 연다</li><li>3막 대가: 가짜 약을 숨기지 않고 로트 번호를 게시한다</li></ul><h2 id="hp07-·-한강교량공회" tabindex="-1">HP07 · 한강교량공회 <a class="header-anchor" href="#hp07-·-한강교량공회" aria-label="Permalink to &quot;HP07 · 한강교량공회&quot;">​</a></h2><ul><li>분류: INFRA_OPERATOR</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S01 여의신정수문정부, S07 용산철도후국, S14 아차구의관문국, S04 뚝도공방연합</li><li>전속 국가: 없음</li><li>스튜어드십: 고서준</li></ul><p>한강 교각 점검로와 잠수교 잔교에서 한강교량공회가 풍속 폐쇄 기준을 지킨다.</p><p>고서준은 풍속이 기준을 넘으면 수운 우선도 세운다.</p><p>여의 수운 우선 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>교량을 통행세로만 계산하지 않는다.</p><h3 id="_3막-20" tabindex="-1">3막 <a class="header-anchor" href="#_3막-20" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 한강 교각 점검로와 잠수교 잔교에서 풍속 폐쇄 기준이 부족해진다</li><li>2막 교섭: 고서준이 여의 수운 우선와 공동 점검을 연다</li><li>3막 대가: 교량을 통행세로만 계산하지 않는다</li></ul><h2 id="hp08-·-시장냉동상단" tabindex="-1">HP08 · 시장냉동상단 <a class="header-anchor" href="#hp08-·-시장냉동상단" aria-label="Permalink to &quot;HP08 · 시장냉동상단&quot;">​</a></h2><ul><li>분류: CIVIC_COMPACT</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S08 노량진남관상회, S15 가락잠실배급국, S02 서남제작동맹</li><li>전속 국가: 없음</li><li>스튜어드십: 구하온</li></ul><p>노량진 냉동고와 가락 얼음 창고에서 시장냉동상단이 전력 슬롯 순환을 지킨다.</p><p>구하온은 모터를 빼 가기 전에 온도 로그를 인쇄한다.</p><p>제작 동맹의 모터 회수 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>온도 로그가 끊기면 경매를 멈춘다.</p><h3 id="_3막-21" tabindex="-1">3막 <a class="header-anchor" href="#_3막-21" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 노량진 냉동고와 가락 얼음 창고에서 전력 슬롯 순환이 부족해진다</li><li>2막 교섭: 구하온이 제작 동맹의 모터 회수와 공동 점검을 연다</li><li>3막 대가: 온도 로그가 끊기면 경매를 멈춘다</li></ul><h2 id="hp09-·-데이터신탁가" tabindex="-1">HP09 · 데이터신탁가 <a class="header-anchor" href="#hp09-·-데이터신탁가" aria-label="Permalink to &quot;HP09 · 데이터신탁가&quot;">​</a></h2><ul><li>분류: DATA_TRUST</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S09 상암송신공사, S16 수서강남협약도시, S03 마곡연구평의회</li><li>전속 국가: 없음</li><li>스튜어드십: 최은재</li></ul><p>상암 로그 신탁과 수서 계약 해시에서 데이터신탁가가 모델 카드 공개를 지킨다.</p><p>최은재는 학습자료 반출 요청에 원본 대신 집계만 넘긴다.</p><p>마곡의 학습자료 반출 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>얼굴 원본을 통행권과 바꾸지 않는다.</p><h3 id="_3막-22" tabindex="-1">3막 <a class="header-anchor" href="#_3막-22" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 상암 로그 신탁과 수서 계약 해시에서 모델 카드 공개가 부족해진다</li><li>2막 교섭: 최은재가 마곡의 학습자료 반출와 공동 점검을 연다</li><li>3막 대가: 얼굴 원본을 통행권과 바꾸지 않는다</li></ul><h2 id="hp10-·-외교통역문" tabindex="-1">HP10 · 외교통역문 <a class="header-anchor" href="#hp10-·-외교통역문" aria-label="Permalink to &quot;HP10 · 외교통역문&quot;">​</a></h2><ul><li>분류: PROFESSIONAL_GUILD</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S06 도성기록청, S16 수서강남협약도시, S09 상암송신공사</li><li>전속 국가: 없음</li><li>스튜어드십: 표시완</li></ul><p>도성 통역석과 수서 세관 창구에서 외교통역문이 언어 쌍 당직을 지킨다.</p><p>표시완은 자동번역이 빨라도 인준 문장은 사람이 읽는다.</p><p>상암의 자동번역 우선 앞에서는 공동 점검만 열고 키는 넘기지 않는다.</p><p>통역을 자백 도구로 돌리지 않는다.</p><h3 id="_3막-23" tabindex="-1">3막 <a class="header-anchor" href="#_3막-23" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 균열: 도성 통역석과 수서 세관 창구에서 언어 쌍 당직이 부족해진다</li><li>2막 교섭: 표시완이 상암의 자동번역 우선와 공동 점검을 연다</li><li>3막 대가: 통역을 자백 도구로 돌리지 않는다</li></ul><h2 id="hc15-·-네이버" tabindex="-1">HC15 · 네이버 <a class="header-anchor" href="#hc15-·-네이버" aria-label="Permalink to &quot;HC15 · 네이버&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S09 상암송신공사, S16 수서강남협약도시, S03 마곡연구평의회</li><li>전속 국가: 없음</li><li>스튜어드십: 류가온</li></ul><p>상암 송신탑 아래 네이버은 끊어진 문서와 방송을 하나의 검색 색인에 묶는다.</p><p>소문마다 검증표와 반론 시각을 달아 판정 자체를 거래할 수 없게 한다.</p><p>류가온은 수서의 계약 장부를 광고칸 입찰 원장과 나란히 공개한다.</p><p>마곡 연구자들은 근거가 바뀔 때마다 이전 판정을 지우지 않고 덧붙인다.</p><p>구매자가 노출 순서를 사더라도 검색 결과의 근거 줄은 건드리지 못한다.</p><p>보호조약 위반 기록이 사라지자 색인관과 경매참관인은 서로 다른 금고를 연다.</p><p>네이버은 조작을 밝히는 대신 가장 큰 광고칸과 남부 통행권을 포기한다.</p><h3 id="_3막-24" tabindex="-1">3막 <a class="header-anchor" href="#_3막-24" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 누락: 상암 송신탑 색인에서 수서의 보호조약 위반 기록이 사라진다</li><li>2막 입찰: 류가온이 마곡 검증관과 광고칸 구매자에게 같은 반론 시간을 건다</li><li>3막 흔적: 낙찰 원장을 공개한 뒤 네이버은 가장 비싼 광고칸을 잃는다</li></ul><h2 id="hc16-·-kt" tabindex="-1">HC16 · KT <a class="header-anchor" href="#hc16-·-kt" aria-label="Permalink to &quot;HC16 · KT&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S09 상암송신공사, S07 용산철도후국, S12 신내망우환승시</li><li>전속 국가: 없음</li><li>스튜어드십: 표윤재</li></ul><p>용산 철도 창고의 KT 교환기는 상암과 신내 사이의 말을 갈아 태운다.</p><p>철길 옆 기지국은 화물차 전지를 빌려 짧은 중계 구간을 이어 간다.</p><p>임대 회선의 사용자는 선로 가문이 아니라 호출 순번으로 정해진다.</p><p>표윤재가 맡은 교환표에는 배차 지시와 의료 요청이 다른 색인으로 기록된다.</p><p>폭우가 지붕 중계기를 꺾자 신내의 환자 이송 신호부터 우회선에 오른다.</p><p>화물 상인들은 손실을 이유로 전용선을 요구하지만 가입자대표가 이를 막는다.</p><p>살아난 통신로의 값으로 KT은 용산 교환실 한 칸의 운영권을 넘긴다.</p><h3 id="_3막-25" tabindex="-1">3막 <a class="header-anchor" href="#_3막-25" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 단절: 용산 철도 창고의 교환기가 꺼져 신내 의료열차 호출이 상암에 닿지 않는다</li><li>2막 우회: 표윤재가 화물 배차 회선을 줄이고 철도 지붕의 임시 중계기를 잇는다</li><li>3막 양도: 의료호출을 살린 대가로 용산 선로 가문에 교환소 한 칸을 내준다</li></ul><h2 id="hc17-·-lg에너지솔루션" tabindex="-1">HC17 · LG에너지솔루션 <a class="header-anchor" href="#hc17-·-lg에너지솔루션" aria-label="Permalink to &quot;HC17 · LG에너지솔루션&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S02 서남제작동맹, S04 뚝도공방연합, S11 창동차륜방</li><li>전속 국가: 없음</li><li>스튜어드십: 배해솔</li></ul><p>구로·금천 제작축에서 LG에너지솔루션은 전지 낱칸을 수명과 온도에 따라 갈라 쌓는다.</p><p>뚝도 공방은 봉인된 전해액 통을 받아 펌프와 소형 기계의 전원 묶음을 만든다.</p><p>창동 차량기지는 제동장치용 물량을 먼저 요구하되 시험표 없는 재료는 받지 않는다.</p><p>배해솔의 인장은 충전량이 아니라 내열 시험과 오염 이력을 보증한다.</p><p>한 통의 누액이 발견되면 같은 운송 수레에 실린 묶음 전체가 격리된다.</p><p>제작 수리반은 부족분을 풀라고 압박하고 북부 기술자는 제동 몫을 지키려 창고문을 막는다.</p><p>재료인증관이 위조 표식을 찾아낸 뒤 공급 순서는 세 국가의 공개 추첨으로 바뀐다.</p><p>LG에너지솔루션은 신뢰를 남기려고 쓸 수 있는 전지까지 폐기하고 창동의 예비 운행을 줄인다.</p><h3 id="_3막-26" tabindex="-1">3막 <a class="header-anchor" href="#_3막-26" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 누액: 구로·금천 비축고의 전해액 통이 새며 뚝도 인증표까지 의심받는다</li><li>2막 배분: 배해솔이 창동 제동전지 몫을 봉인하고 제작동맹 수리반과 재검사 순서를 다툰다</li><li>3막 폐기: 오염 묶음을 전량 버려 북부 열차의 예비 운행 한 차례를 포기한다</li></ul><h2 id="hc18-·-hmm" tabindex="-1">HC18 · HMM <a class="header-anchor" href="#hc18-·-hmm" aria-label="Permalink to &quot;HC18 · HMM&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S07 용산철도후국, S08 노량진남관상회, S15 가락잠실배급국</li><li>전속 국가: 없음</li><li>스튜어드십: 차윤호</li></ul><p>용산 북안의 녹슨 기중기 아래에서 HMM이 바지선 선석을 배정한다.</p><p>차윤호는 한강 교량의 통과 시각을 철도 배차표와 나란히 적는다.</p><p>노량진에서 실린 냉동 상자는 봉인표가 온전해야 가락 도매 경매장으로 향한다.</p><p>옛 항공 화물 규격은 무게와 파손 책임을 가르는 장부 규칙으로 남아 있다.</p><p>선주들은 빠른 항로를 요구하지만 나루참관은 공공 화물의 우선권을 확인한다.</p><p>좌초선이 물길을 막자 세 국가는 각자 부두 권리를 내세운다.</p><p>HMM은 독점 선석을 버리는 대신 모든 하역료와 운항 순서를 공개한다.</p><h3 id="_3막-27" tabindex="-1">3막 <a class="header-anchor" href="#_3막-27" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 잠긴 부두: 한강 교량 아래 좌초선이 용산 강변 물류와 바지선 항로를 함께 막는다</li><li>2막 세 나루의 값: 차윤호가 노량진 냉동 화물과 가락 경매 반입권을 묶은 부두 협상을 연다</li><li>3막 빈 상자의 항로: 독점 부두를 포기하고 모든 봉인 화물에 같은 선석 원장을 적용한다</li></ul><h2 id="hc19-·-호텔신라" tabindex="-1">HC19 · 호텔신라 <a class="header-anchor" href="#hc19-·-호텔신라" aria-label="Permalink to &quot;HC19 · 호텔신라&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S06 도성기록청, S15 가락잠실배급국, S16 수서강남협약도시</li><li>전속 국가: 없음</li><li>스튜어드십: 서해진</li></ul><p>도성 의전길에는 호텔신라가 관리하는 중립 객사가 흩어져 있다.</p><p>사절은 무기를 맡기고도 숙박 채무 때문에 붙잡히지 않는다.</p><p>연회 물자는 가락 도매 경매장에서 공개 낙찰한 뒤 품목별 표찰을 단다.</p><p>서해진은 수서의 계약 감사관에게 객실표와 잔치 신용 원장을 함께 내민다.</p><p>오래된 면세 창고에는 화려한 물건보다 조약 답례용 수공품이 쌓인다.</p><p>배급이 모자란 날에는 연회상이 먼저 줄고 일반 숙객의 죽은 그대로 남는다.</p><p>숨은 보증인이 드러나면 손님참관이 의전 서열과 무관하게 거래를 취소한다.</p><h3 id="_3막-28" tabindex="-1">3막 <a class="header-anchor" href="#_3막-28" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 빈 연회석: 도성 의전 회담을 앞두고 가락 경매장의 연회 물자 인도표가 사라진다</li><li>2막 향응의 장부: 서해진이 수서 계약감사 앞에서 객실 배정과 잔치 신용의 숨은 보증인을 밝힌다</li><li>3막 문밖의 선물: 특권 손님용 면세 창고를 열어 기근 배급과 외교 답례품을 분리한다</li></ul><h2 id="hc20-·-hybe" tabindex="-1">HC20 · HYBE <a class="header-anchor" href="#hc20-·-hybe" aria-label="Permalink to &quot;HC20 · HYBE&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S06 도성기록청, S15 가락잠실배급국, S09 상암송신공사</li><li>전속 국가: 없음</li><li>스튜어드십: 백소원</li></ul><p>상암 송신탑이 켜지는 저녁마다 HYBE은 공연 순서를 봉인한다.</p><p>백소원은 노래 한 편의 권리와 방송 한 칸의 값을 서로 다른 원장에 적는다.</p><p>도성 의전 무대에 오른 연희자는 기록청의 인준 아래 이름과 귀환 통행을 보장받는다.</p><p>가락 집결장에서는 유료 입장표 세 장마다 피난민 좌석 하나를 비워 둔다.</p><p>채널 길드가 인기 순서만 밀어붙이면 관객참관이 편성회의를 중지한다.</p><p>위조표 소동은 표 수입뿐 아니라 송신탑의 검증 신뢰까지 흔든다.</p><p>HYBE은 마지막 방송 시간을 각국 증언에 나누고 독점권 해제 내역을 공개한다.</p><h3 id="_3막-29" tabindex="-1">3막 <a class="header-anchor" href="#_3막-29" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 끊긴 후렴: 상암 송신탑의 황금 시간 편성표에서 도성 의전 공연 한 편이 지워진다</li><li>2막 표 없는 군중: 가락 집결장에 위조 입장표가 퍼지자 백소원이 공연권 원장과 방송 기록을 맞댄다</li><li>3막 마지막 송출: 독점 공연권을 짧게 풀어 각 국가의 증언을 같은 방송 시간으로 내보낸다</li></ul><h2 id="hc21-·-카카오" tabindex="-1">HC21 · 카카오 <a class="header-anchor" href="#hc21-·-카카오" aria-label="Permalink to &quot;HC21 · 카카오&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S09 상암송신공사, S16 수서강남협약도시, S12 신내망우환승시</li><li>전속 국가: 없음</li><li>스튜어드십: 심하루</li></ul><p>상암 옛 사옥 지하 중계실에서 카카오가 환승 결제 회선을 지킨다.</p><p>심하루는 메신저 큐와 결제 원장을 서로 다른 축전 칸에 나눠 묶는다.</p><p>수서 협약도시의 장부 공증 요구가 오면 감사 열람권만 열고 서명 키는 넘기지 않는다.</p><p>신내망우환승시의 호출 창구는 어느 진영의 병력도 우선하지 못하게 대기열 규칙으로 막아 둔다.</p><p>회선이 죽어도 마지막 정산 블록은 종이로 남긴다.</p><h3 id="_3막-30" tabindex="-1">3막 <a class="header-anchor" href="#_3막-30" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 단절: 수서 결제 장부 동기가 끊기고 환승 호출이 쌓인다</li><li>2막 중계: 심하루가 상암 송신 검증과 신내 환승 중립 사이에서 회선 분할을 협상한다</li><li>3막 회선: 메신저 중계는 줄이지만 결제 원장은 통째로 남긴다</li></ul><h2 id="hc22-·-테슬라코리아" tabindex="-1">HC22 · 테슬라코리아 <a class="header-anchor" href="#hc22-·-테슬라코리아" aria-label="Permalink to &quot;HC22 · 테슬라코리아&quot;">​</a></h2><ul><li>분류: CORPORATION</li><li>상태: ACTIVE</li><li>출처층: original-fiction</li><li>연결 국가: S03 마곡연구평의회, S09 상암송신공사, S11 창동차륜방</li><li>전속 국가: 없음</li><li>스튜어드십: 백선우</li></ul><p>마곡 연구 부지 끝의 자율 시험선 옆에서 테슬라코리아가 저장에너지 창고를 지킨다.</p><p>백선우는 붕괴 전 규격의 충전 단자와 시험선 차단기를 함께 관리한다.</p><p>곤충·공룡·심층 형태의 옛 시험 기체들이 시험선 밑에서 스스로 깨어나는 일이 있으면, 도면 열쇠는 절반만 꺼내 마곡 평의회 감시 아래 둔다.</p><p>창동 기지의 충전 회선이 불안해지면 규격 인증을 잠시 닫고 회선부터 고른다.</p><p>창고가 비어도 인증 도장은 위조하지 않는다.</p><h3 id="_3막-31" tabindex="-1">3막 <a class="header-anchor" href="#_3막-31" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막 경보: 마곡 시험선 밑 로스트 라인 잔류 신호가 다시 오른다</li><li>2막 분할: 백선우가 도면 열쇠를 마곡 평의회와 상암 공사에 나눠 맡긴다</li><li>3막 봉인: 시험선은 다시 자물쇠 아래 들어가고 충전 규격만 남는다</li></ul>',279)])])}const b=i(r,[["render",o]]);export{s as __pageData,b as default};
